import React, { useState } from "react";
import Registration from "./Registration";
import RoutePlanner from "./RoutePlanner";
import SafetyCheck from "./SafetyCheck";

function App() {
  const [tourist, setTourist] = useState(null);
  const [showRoutePlanner, setShowRoutePlanner] = useState(false);
  const [showSafetyCheck, setShowSafetyCheck] = useState(false);

  // Step 1: Registration first
  if (!tourist) {
    return <Registration onRegistered={() => setShowRoutePlanner(true)} />;
  }

  // Step 2: Route Planner after registration
  if (showRoutePlanner && !showSafetyCheck) {
    return (
      <RoutePlanner
        tourist={tourist}
        onProceedToSafetyCheck={() => setShowSafetyCheck(true)}
      />
    );
  }

  // Step 3: Safety Check (after route planning)
  if (showSafetyCheck) {
    return <SafetyCheck tourist={tourist} />;
  }

  // Fallback
  return <Registration onRegistered={setTourist} />;
}

export default App;
